// FIGURE themes: the parser of the theme format (figure_theme.h) and the embedded themes (themes/*.toml).
#include "figure_theme.h"

#include <cctype>
#include <cstdlib>
#include <string>

namespace {

#include "figure_themes.inc" // generated by native/CMakeLists.txt: THEMES[] = {{name, text}, ...}

std::string trim(const std::string &s) {
   size_t a = 0, b = s.size();
   while (a < b && std::isspace(static_cast<unsigned char>(s[a]))) ++a;
   while (b > a && std::isspace(static_cast<unsigned char>(s[b - 1]))) --b;
   return s.substr(a, b - a);
}

// strip a comment ('#' outside a string; a string's own '#' is a hex colour)
std::string strip_comment(const std::string &line) {
   bool in_string = false;
   for (size_t i = 0; i < line.size(); ++i) {
      if (line[i] == '"') in_string = !in_string;
      else if (line[i] == '#' && !in_string) return line.substr(0, i);
   }
   return line;
}

// a value: "string", number, true/false, or [v, v, ...] (one level)
struct value_t {
   enum kind_t { STRING, NUMBER, BOOL, ARRAY } kind = NUMBER;
   std::string          str;
   double               num = 0.0;
   std::vector<value_t> items;
};

bool parse_scalar(const std::string &t, value_t &v) {
   if (t.size() >= 2 && t.front() == '"' && t.back() == '"') {
      v.kind = value_t::STRING;
      v.str = t.substr(1, t.size() - 2);
      return v.str.find('"') == std::string::npos;
   }
   if (t == "true" || t == "false") {
      v.kind = value_t::BOOL;
      v.num = t == "true" ? 1.0 : 0.0;
      return true;
   }
   char *end = nullptr;
   v.kind = value_t::NUMBER;
   v.num = std::strtod(t.c_str(), &end);
   return !t.empty() && end && *end == '\0';
}

bool parse_value(const std::string &text, value_t &v) {
   const std::string t = trim(text);
   if (t.empty()) return false;
   if (t.front() != '[') return parse_scalar(t, v);
   if (t.back() != ']') return false;
   v.kind = value_t::ARRAY;
   const std::string inner = trim(t.substr(1, t.size() - 2));
   if (inner.empty()) return true;
   size_t start = 0;
   bool in_string = false;
   for (size_t i = 0; i <= inner.size(); ++i) {
      if (i < inner.size() && inner[i] == '"') in_string = !in_string;
      if (i == inner.size() || (inner[i] == ',' && !in_string)) {
         value_t item;
         if (!parse_scalar(trim(inner.substr(start, i - start)), item)) return false;
         v.items.push_back(item);
         start = i + 1;
      }
   }
   return !in_string;
}

bool hex_color(const std::string &s, figure_theme::color_t &c) {
   std::string h = s;
   if (!h.empty() && h[0] == '#') h = h.substr(1);
   if (h.size() != 6 && h.size() != 8) return false;
   for (char ch : h)
      if (!std::isxdigit(static_cast<unsigned char>(ch))) return false;
   auto byte = [&](int k) { return static_cast<float>(std::strtol(h.substr(2 * k, 2).c_str(), nullptr, 16)) / 255.0f; };
   c.r = byte(0);
   c.g = byte(1);
   c.b = byte(2);
   c.a = h.size() == 8 ? byte(3) : 1.0f;
   return true;
}

// a colour value: "#rrggbb[aa]" or ["#rrggbb", alpha]
bool color_value(const value_t &v, figure_theme::color_t &c) {
   if (v.kind == value_t::STRING) return hex_color(v.str, c);
   if (v.kind == value_t::ARRAY && v.items.size() == 2 && v.items[0].kind == value_t::STRING &&
       v.items[1].kind == value_t::NUMBER && hex_color(v.items[0].str, c)) {
      if (!(v.items[1].num >= 0.0 && v.items[1].num <= 1.0)) return false;
      c.a = static_cast<float>(v.items[1].num);
      return true;
   }
   return false;
}

} // namespace

namespace figure_theme {

bool parse(const std::string &text, const std::string &where, theme_t &theme, std::string &err) {
   theme = theme_t{};
   std::string section;
   size_t pos = 0;
   int lineno = 0;
   auto fail = [&](const std::string &msg) {
      err = where + ":" + std::to_string(lineno) + ": " + msg;
      return false;
   };
   while (pos <= text.size()) {
      const size_t nl = text.find('\n', pos);
      const std::string raw = text.substr(pos, nl == std::string::npos ? std::string::npos : nl - pos);
      pos = nl == std::string::npos ? text.size() + 1 : nl + 1;
      ++lineno;
      const std::string line = trim(strip_comment(raw));
      if (line.empty()) continue;
      if (line.front() == '[' && line.back() == ']' && line.find('=') == std::string::npos) {
         section = trim(line.substr(1, line.size() - 2));
         if (section != "imgui.colors" && section != "imgui.vars" && section != "implot.colors" &&
             section != "implot.vars")
            return fail("unknown section [" + section + "] (imgui.colors, imgui.vars, implot.colors, implot.vars)");
         continue;
      }
      const size_t eq = line.find('=');
      if (eq == std::string::npos) return fail("expected name = value");
      const std::string key = trim(line.substr(0, eq));
      value_t v;
      if (key.empty() || !parse_value(line.substr(eq + 1), v)) return fail("cannot read the value of \"" + key + "\"");
      if (section.empty()) {
         if (key == "base") {
            if (v.kind != value_t::STRING || (v.str != "dark" && v.str != "light" && v.str != "classic"))
               return fail("base must be \"dark\", \"light\" or \"classic\"");
            theme.base = v.str;
         } else if (key == "background") {
            if (!color_value(v, theme.background)) return fail("background must be a colour \"#rrggbb\"");
            theme.has_background = true;
         } else if (key == "font") {
            if (v.kind != value_t::STRING || v.str.empty()) return fail("font must be \"plex-sans\", \"proggy\" or a file");
            theme.font = v.str;
         } else if (key == "font_size") {
            if (v.kind != value_t::NUMBER || !(v.num > 0.0 && v.num <= 200.0)) return fail("font_size must be in (0, 200]");
            theme.font_size = v.num;
         } else if (key == "lines") {
            if (v.kind == value_t::STRING) {
               if (!line_palette(v.str, theme.lines)) return fail("lines: unknown palette \"" + v.str + "\" (okabe-ito)");
               continue;
            }
            if (v.kind != value_t::ARRAY || v.items.empty()) return fail("lines must be a list of colours or a palette");
            for (const value_t &item : v.items) {
               color_t c;
               if (!color_value(item, c)) return fail("lines: \"" + item.str + "\" is not a colour");
               theme.lines.push_back(c);
            }
         } else {
            return fail("unknown key \"" + key + "\" (base, background, font, font_size, lines, or a [section])");
         }
         continue;
      }
      entry_t e;
      e.name = key;
      e.line = lineno;
      if (section == "imgui.colors" || section == "implot.colors") {
         if (!color_value(v, e.color)) return fail(key + ": a colour is \"#rrggbb\", \"#rrggbbaa\" or [\"#rrggbb\", alpha]");
         (section == "imgui.colors" ? theme.imgui_colors : theme.implot_colors).push_back(e);
      } else {
         if (v.kind == value_t::NUMBER || v.kind == value_t::BOOL) {
            e.values = {v.num};
         } else if (v.kind == value_t::ARRAY && v.items.size() == 2 && v.items[0].kind == value_t::NUMBER &&
                    v.items[1].kind == value_t::NUMBER) {
            e.values = {v.items[0].num, v.items[1].num};
         } else {
            return fail(key + ": a variable is a number, [x, y], true or false");
         }
         (section == "imgui.vars" ? theme.imgui_vars : theme.implot_vars).push_back(e);
      }
   }
   return true;
}

bool line_palette(const std::string &name, std::vector<color_t> &lines) {
   // Okabe & Ito (2008), "Color Universal Design": orange, sky blue, bluish green, yellow, blue, vermilion, reddish
   // purple (its eighth colour, black, is left out: invisible on dark backgrounds)
   static const char *OKABE_ITO[] = {"#e69f00", "#56b4e9", "#009e73", "#f0e442", "#0072b2", "#d55e00", "#cc79a7"};
   if (name != "okabe-ito") return false;
   lines.clear();
   for (const char *h : OKABE_ITO) {
      color_t c;
      hex_color(h, c);
      lines.push_back(c);
   }
   return true;
}

int builtin_count() { return static_cast<int>(sizeof(THEMES) / sizeof(THEMES[0])); }
const char *builtin_name(int i) { return THEMES[i].name; }
const char *builtin_text(int i) { return THEMES[i].text; }

} // namespace figure_theme
